import { Schema } from "effect";

export const RichTextLink = Schema.String.check(
  Schema.isMaxLength(2000),
  Schema.makeFilter((value) => {
    if (/[\s\p{Cc}\\{}]/u.test(value)) return false;
    const url = URL.parse(value);
    return (
      url !== null &&
      ["https:", "mailto:"].includes(url.protocol) &&
      !url.username &&
      !url.password
    );
  }),
).annotate({ identifier: "RichTextLink" });

export const RichTextMarks = Schema.Struct({
  bold: Schema.optional(Schema.Boolean),
  italic: Schema.optional(Schema.Boolean),
  underline: Schema.optional(Schema.Boolean),
  href: Schema.optional(RichTextLink),
}).annotate({ identifier: "RichTextMarks" });

export const RichTextInline = Schema.Union([
  Schema.Struct({
    type: Schema.Literal("text"),
    text: Schema.String.check(Schema.isMaxLength(20000)),
    marks: Schema.optional(RichTextMarks),
  }),
  Schema.Struct({
    type: Schema.Literal("variable"),
    key: Schema.String.check(Schema.isPattern(/^[a-zA-Z][a-zA-Z0-9_.]{0,79}$/)),
    marks: Schema.optional(RichTextMarks),
  }),
]).annotate({ identifier: "RichTextInline" });

export const RichTextBlockKind = Schema.Literals([
  "paragraph",
  "heading",
  "bullet",
  "numbered",
]).annotate({ identifier: "RichTextBlockKind" });
export const RichTextDocument = Schema.Struct({
  version: Schema.Literal(1),
  blocks: Schema.Array(
    Schema.Struct({
      type: RichTextBlockKind,
      content: Schema.Array(RichTextInline).check(Schema.isMaxLength(2000)),
    }),
  ).check(Schema.isMinLength(1), Schema.isMaxLength(100)),
})
  .check(
    Schema.makeFilter(
      (value) =>
        value.blocks.reduce(
          (size, block) =>
            size +
            block.content.reduce(
              (count, inline) =>
                count + (inline.type === "text" ? inline.text.length : 1),
              0,
            ),
          0,
        ) <= 20000,
    ),
  )
  .annotate({ identifier: "RichTextDocument" });

export const RichTextVariable = Schema.Struct({
  key: Schema.String.check(Schema.isPattern(/^[a-zA-Z][a-zA-Z0-9_.]{0,79}$/)),
  label: Schema.String,
  type: Schema.Literals(["text", "url"]),
  sample: Schema.String,
}).annotate({ identifier: "RichTextVariable" });

export type RichTextDocument = typeof RichTextDocument.Type;
export type RichTextInline = typeof RichTextInline.Type;
export type RichTextMarks = typeof RichTextMarks.Type;
export type RichTextBlockKind = typeof RichTextBlockKind.Type;
export type RichTextVariable = typeof RichTextVariable.Type;

import { Schema } from "effect";
import {
  RichTextDocument,
  RichTextMarks,
  type RichTextInline,
  type RichTextBlockKind,
} from "./schema";

export type TextSelection = { from: number; to: number };
export type RichTextEdit = {
  value: RichTextDocument;
  selection: TextSelection;
};
type Unit = RichTextInline | { type: "break"; next: RichTextBlockKind };
const sameMarks = Schema.toEquivalence(RichTextMarks);

export const emptyRichText = (): RichTextDocument => ({
  version: 1,
  blocks: [{ type: "paragraph", content: [] }],
});
export const richTextFromString = (text: string): RichTextDocument => ({
  version: 1,
  blocks: text.split(/\r\n?|\n/).map((line) => ({
    type: "paragraph",
    content: line ? [{ type: "text", text: line }] : [],
  })),
});
export const richTextPlainText = (
  value: RichTextDocument,
  variables?: Readonly<Record<string, string>>,
) =>
  value.blocks
    .map((block) =>
      block.content
        .map((inline) =>
          inline.type === "text"
            ? inline.text
            : (variables?.[inline.key] ?? `{{${inline.key}}}`),
        )
        .join(""),
    )
    .join("\n");

/** Convert plain template tokens to atomic variables without changing their keys. */
export const richTextFromTemplate = (text: string): RichTextDocument => ({
  version: 1,
  blocks: [{
    type: "paragraph",
    content: text.split(/(\{\{[a-zA-Z][a-zA-Z0-9_.]*\}\})/g).filter(Boolean).map((part) =>
      /^\{\{[a-zA-Z][a-zA-Z0-9_.]*\}\}$/.test(part)
        ? { type: "variable", key: part.slice(2, -2) }
        : { type: "text", text: part },
    ),
  }],
});

const units = (value: RichTextDocument): Unit[] =>
  value.blocks.flatMap((block, index) => [
    ...(index ? [{ type: "break", next: block.type } satisfies Unit] : []),
    ...block.content.flatMap<Unit>((inline) =>
      inline.type === "text"
        ? inline.text.split("").map((text) => ({ ...inline, text }))
        : [inline],
    ),
  ]);

const fromUnits = (
  content: readonly Unit[],
  first: RichTextBlockKind,
): RichTextDocument => {
  const blocks: Array<{ type: RichTextBlockKind; content: RichTextInline[] }> =
    [{ type: first, content: [] }];
  for (const unit of content) {
    if (unit.type === "break") {
      blocks.push({ type: unit.next, content: [] });
      continue;
    }
    const target = blocks.at(-1);
    if (!target) continue;
    const previous = target.content.at(-1);
    if (
      unit.type === "text" &&
      previous?.type === "text" &&
      sameMarks(previous.marks ?? {}, unit.marks ?? {})
    ) {
      target.content[target.content.length - 1] = {
        ...previous,
        text: previous.text + unit.text,
      };
    } else target.content.push(unit);
  }
  return { version: 1, blocks };
};

export const replaceRichText = (
  value: RichTextDocument,
  selection: TextSelection,
  inserted: RichTextInline,
): RichTextEdit => {
  const content = units(value);
  const from = Math.max(0, Math.min(selection.from, content.length));
  const to = Math.max(from, Math.min(selection.to, content.length));
  const additions: Unit[] =
    inserted.type === "text"
      ? inserted.text
          .replace(/\r\n?/g, "\n")
          .split("")
          .map((text) =>
            text === "\n"
              ? { type: "break", next: "paragraph" }
              : { type: "text", text, marks: inserted.marks },
          )
      : [inserted];
  const next = fromUnits(
    [...content.slice(0, from), ...additions, ...content.slice(to)],
    value.blocks[0]?.type ?? "paragraph",
  );
  const position = from + additions.length;
  return { value: next, selection: { from: position, to: position } };
};

export const formatRichText = (
  value: RichTextDocument,
  selection: TextSelection,
  mark: keyof RichTextMarks,
  setting: string | boolean | undefined,
): RichTextDocument =>
  fromUnits(
    units(value).map((unit, index) => {
      if (
        unit.type === "break" ||
        index < selection.from ||
        index >= selection.to
      )
        return unit;
      const marks = { ...unit.marks, [mark]: setting };
      return { ...unit, marks };
    }),
    value.blocks[0]?.type ?? "paragraph",
  );

export const setRichTextBlock = (
  value: RichTextDocument,
  selection: TextSelection,
  type: RichTextBlockKind,
): RichTextDocument => {
  let offset = 0;
  return {
    ...value,
    blocks: value.blocks.map((block) => {
      const start = offset;
      offset +=
        block.content.reduce(
          (size, inline) =>
            size + (inline.type === "text" ? inline.text.length : 1),
          0,
        ) + 1;
      return selection.from < offset && selection.to >= start
        ? { ...block, type }
        : block;
    }),
  };
};

export const richTextLength = (value: RichTextDocument) => units(value).length;
export const richTextMarksAt = (
  value: RichTextDocument,
  position: number,
): RichTextMarks => {
  const content = units(value);
  const unit = content[Math.max(0, position - 1)];
  return unit && unit.type !== "break" ? (unit.marks ?? {}) : {};
};

import { Option, Schema } from "effect";
import {
  RichTextDocument,
  RichTextLink,
  RichTextMarks,
  type RichTextBlockKind,
  type RichTextInline,
  type RichTextVariable,
} from "./schema";
import { emptyRichText, type TextSelection } from "./model";

type Point = { node: Node; offset: number };
const blocks = new Set(["P", "DIV", "H1", "H2", "H3", "LI"]);
const sameMarks = Schema.toEquivalence(RichTextMarks);
const pointAfter = (node: Node): Point => ({
  node: node.parentNode ?? node,
  offset: Array.from<Node>(node.parentNode?.childNodes ?? []).indexOf(node) + 1,
});

/** Normalize browser editing DOM to the allowlisted model; never retain arbitrary HTML. */
export const readRichTextDOM = (root: HTMLElement) => {
  const result: Array<{ type: RichTextBlockKind; content: RichTextInline[] }> =
    [];
  const points: Point[] = [{ node: root, offset: 0 }];
  let current:
    { type: RichTextBlockKind; content: RichTextInline[] } | undefined;
  const begin = (type: RichTextBlockKind, point: Point) => {
    if (current) result.push(current);
    if (result.length) points.push(point);
    else points[0] = point;
    current = { type, content: [] };
  };
  const append = (inline: RichTextInline, point: Point) => {
    if (!current) begin("paragraph", point);
    const previous = current?.content.at(-1);
    if (
      inline.type === "text" &&
      previous?.type === "text" &&
      sameMarks(inline.marks ?? {}, previous.marks ?? {})
    ) {
      if (current)
        current.content[current.content.length - 1] = {
          ...previous,
          text: previous.text + inline.text,
        };
    } else current?.content.push(inline);
    points.push(point);
  };
  const visit = (
    node: Node,
    inherited: RichTextMarks = {},
    kind: RichTextBlockKind = "paragraph",
  ) => {
    if (node instanceof Text) {
      if (!current) begin(kind, { node, offset: 0 });
      for (let index = 0; index < node.data.length; index++)
        append(
          { type: "text", text: node.data[index] ?? "", marks: inherited },
          { node, offset: index + 1 },
        );
      return;
    }
    if (
      !(node instanceof HTMLElement) ||
      ["SCRIPT", "STYLE", "IFRAME"].includes(node.tagName)
    )
      return;
    const key = node.dataset.richVariable;
    if (key) {
      const variable = { type: "variable", key, marks: inherited } as const;
      append(variable, pointAfter(node));
      return;
    }
    const href = node.getAttribute("href");
    const marks = {
      bold: inherited.bold,
      italic: inherited.italic,
      underline: inherited.underline,
      href: inherited.href,
    };
    if (
      ["B", "STRONG"].includes(node.tagName) ||
      node.style.fontWeight === "700"
    )
      marks.bold = true;
    if (["I", "EM"].includes(node.tagName) || node.style.fontStyle === "italic")
      marks.italic = true;
    if (node.tagName === "U" || node.style.textDecoration.includes("underline"))
      marks.underline = true;
    if (href && Schema.is(RichTextLink)(href)) marks.href = href;
    const type =
      node.dataset.richKind === "bullet"
        ? "bullet"
        : node.dataset.richKind === "numbered"
          ? "numbered"
          : /^H[123]$/.test(node.tagName)
            ? "heading"
            : node.tagName === "LI"
              ? node.parentElement?.tagName === "OL"
                ? "numbered"
                : "bullet"
              : kind;
    const isBlock = blocks.has(node.tagName);
    const container =
      isBlock && [...node.children].some((child) => blocks.has(child.tagName));
    if (isBlock && !container) begin(type, { node, offset: 0 });
    if (node.tagName === "BR") {
      // An empty block's last BR is a browser caret placeholder.
      if (node.nextSibling) begin(kind, pointAfter(node));
      return;
    }
    for (const child of node.childNodes) visit(child, marks, type);
  };
  for (const child of root.childNodes) visit(child);
  if (current) result.push(current);
  const value = Option.getOrUndefined(
    Schema.decodeOption(RichTextDocument)({
      version: 1,
      blocks: result.length ? result : emptyRichText().blocks,
    }),
  );
  return { value, points };
};

export const readEditorSelection = (
  root: HTMLElement,
  points: readonly Point[],
): TextSelection | undefined => {
  const selection = root.ownerDocument.getSelection();
  if (
    !selection?.anchorNode ||
    !selection.focusNode ||
    !root.contains(selection.anchorNode) ||
    !root.contains(selection.focusNode)
  )
    return;
  const position = (node: Node, offset: number) => {
    const range = root.ownerDocument.createRange();
    range.setStart(node, offset);
    range.collapse(true);
    let result = 0;
    points.forEach((point, index) => {
      if (
        root.contains(point.node) &&
        range.comparePoint(point.node, point.offset) <= 0
      )
        result = index;
    });
    return result;
  };
  const anchor = position(selection.anchorNode, selection.anchorOffset);
  const focus = position(selection.focusNode, selection.focusOffset);
  return { from: Math.min(anchor, focus), to: Math.max(anchor, focus) };
};

export const restoreRichTextSelection = (
  root: HTMLElement,
  selection: TextSelection,
) => {
  const { points } = readRichTextDOM(root);
  const start = points[Math.min(selection.from, points.length - 1)];
  const end = points[Math.min(selection.to, points.length - 1)];
  if (!start || !end) return;
  const range = root.ownerDocument.createRange();
  range.setStart(start.node, start.offset);
  range.setEnd(end.node, end.offset);
  root.ownerDocument.getSelection()?.removeAllRanges();
  root.ownerDocument.getSelection()?.addRange(range);
};

/** DOM creation, not HTML interpolation, keeps variable values and text escaped. */
export const writeRichTextDOM = (
  root: HTMLElement,
  value: RichTextDocument,
  variables: readonly RichTextVariable[],
) => {
  const children = value.blocks.map((block) => {
    const paragraph = root.ownerDocument.createElement(
      block.type === "heading" ? "h2" : "div",
    );
    if (block.type === "heading")
      paragraph.style.cssText = "font-size:1.4em;font-weight:700";
    if (block.type === "bullet" || block.type === "numbered") {
      paragraph.dataset.richKind = block.type;
      paragraph.style.cssText = `display:list-item;margin-left:1.5em;list-style-type:${block.type === "bullet" ? "disc" : "decimal"}`;
    }
    for (const inline of block.content) {
      const span = root.ownerDocument.createElement(
        inline.marks?.href ? "a" : "span",
      );
      if (inline.type === "variable") {
        span.dataset.richVariable = inline.key;
        span.contentEditable = "false";
        span.textContent = `{{${variables.find((item) => item.key === inline.key)?.label ?? inline.key}}}`;
        span.className =
          "mx-0.5 inline-block rounded bg-indigo-50 px-1 font-mono text-[0.85em] text-indigo-800";
      } else span.textContent = inline.text;
      if (inline.marks?.bold) span.style.fontWeight = "700";
      if (inline.marks?.italic) span.style.fontStyle = "italic";
      if (inline.marks?.underline) span.style.textDecoration = "underline";
      if (inline.marks?.href) {
        span.setAttribute("href", inline.marks.href);
        span.style.textDecoration = "underline";
      }
      paragraph.append(span);
    }
    if (!block.content.length)
      paragraph.append(root.ownerDocument.createElement("br"));
    return paragraph;
  });
  root.replaceChildren(...children);
};
